settings.custom_css:
selector { position: relative; }
/* iconos desde la Biblioteca de medios (máscara: no se duplican al importar y toman el color del estado) */
selector .ak-dip-tabs .e-n-tab-title-text { display: flex !important; align-items: center; gap: 24px; }
selector .ak-dip-tabs .e-n-tab-title-text::before, selector .ak-dip-ic { content: ""; flex: 0 0 auto; background-color: #838994;
  -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-position: center; mask-position: center; -webkit-mask-size: contain; mask-size: contain; transition: background-color .2s; }
selector .ak-dip-tabs .e-n-tab-title-text::before { width: 34px; height: 34px; }
selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"] .e-n-tab-title-text::before { background-color: #C49A45; }
selector .ak-dip-ic { width: 60px !important; height: 60px; min-height: 0 !important; padding: 0 !important; background-color: #C49A45; }
selector .ak-dip-tabs .e-n-tab-title:nth-child(1) .e-n-tab-title-text::before, selector .ak-dip-ic-1 { -webkit-mask-image: url(https://grupogoberna.com/wp-content/uploads/2026/09/programa-objetivo.svg); mask-image: url(https://grupogoberna.com/wp-content/uploads/2026/09/programa-objetivo.svg); }
selector .ak-dip-tabs .e-n-tab-title:nth-child(2) .e-n-tab-title-text::before, selector .ak-dip-ic-2 { -webkit-mask-image: url(https://grupogoberna.com/wp-content/uploads/2026/09/programa-para-quien.svg); mask-image: url(https://grupogoberna.com/wp-content/uploads/2026/09/programa-para-quien.svg); }
selector .ak-dip-tabs .e-n-tab-title:nth-child(3) .e-n-tab-title-text::before, selector .ak-dip-ic-3 { -webkit-mask-image: url(https://grupogoberna.com/wp-content/uploads/2026/09/programa-que-lograras.svg); mask-image: url(https://grupogoberna.com/wp-content/uploads/2026/09/programa-que-lograras.svg); }
selector .elementor-widget-text-editor p { margin: 0 0 22px; }
selector .elementor-widget-text-editor p:last-child { margin-bottom: 0; }
/* ---- pestañas: opciones en el lado oscuro, contenido en el panel claro ---- */
selector .ak-dip-tabs, selector .ak-dip-tabs > .elementor-widget-container { width: 100%; }
selector .ak-dip-tabs .e-n-tabs { display: grid !important; grid-template-columns: 45.4% 54.6%; gap: 0 !important; --n-tabs-gap: 0px; min-height: 717px; }
selector .ak-dip-tabs .e-n-tabs-heading { display: flex !important; flex-direction: column !important; align-items: flex-end !important; justify-content: flex-start !important;
  gap: 0 !important; background: #030917; padding: 407px 79px 100px 40px; margin: 0 !important; }
selector .ak-dip-tabs .e-n-tab-title { position: relative; width: 523px !important; max-width: 100%; flex: 0 0 auto !important; min-height: 90px; height: auto;
  display: flex !important; flex-direction: row !important; align-items: center !important; justify-content: flex-start !important; gap: 24px !important;
  padding: 0 4px 0 12px !important; margin: 0 !important; background: none !important; border: 0 !important; border-bottom: 1px solid #202B45 !important; border-radius: 0 !important; cursor: pointer; }
selector .ak-dip-tabs .e-n-tab-title::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 5px; background: transparent; transition: background .2s; }
selector .ak-dip-tabs .e-n-tab-title::after { content: ""; flex: 0 0 auto; width: 8px; height: 8px; margin-right: 6px; border-top: 2px solid #838994; border-right: 2px solid #838994; transform: rotate(45deg); transition: border-color .2s; }
selector .ak-dip-tabs .e-n-tab-icon { order: 0; flex: 0 0 auto; display: flex; align-items: center; justify-content: center; width: 34px; }
selector .ak-dip-tabs .e-n-tab-icon i, selector .ak-dip-tabs .e-n-tab-icon i:first-child { font-size: 30px; color: #838994; transition: color .2s; }
selector .ak-dip-tabs .e-n-tab-icon svg { width: 30px; height: 30px; fill: #838994; transition: fill .2s; }
selector .ak-dip-tabs .e-n-tab-title-text { order: 1; flex: 1 1 auto; min-width: 0; text-align: left !important; font: 500 20px/1.2 Montserrat, sans-serif !important; text-transform: uppercase; color: #838994 !important; transition: color .2s; }
selector .ak-dip-tabs .e-n-tab-title::after { order: 2; }
selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"]::before { background: #C49A45; }
selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"] .e-n-tab-title-text { color: #C49A45 !important; }
selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"] .e-n-tab-icon i { color: #C49A45; }
selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"] .e-n-tab-icon svg { fill: #C49A45; }
selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"]::after { border-color: #C49A45; }
selector .ak-dip-tabs .e-n-tab-title:focus-visible { outline: 2px solid #C49A45; outline-offset: -2px; }
selector .ak-dip-tabs .e-n-tabs-content { background: #EBEFF2; padding: 83px 40px 80px 132px; margin: 0 !important; }
selector .ak-dip-tabs .e-n-tabs-content > .e-con { max-width: 600px; padding: 0 !important; border: 0 !important; background: none !important; }
selector .ak-dip-tabs .e-n-tabs-content > .e-con.e-active { animation: akDipFade .4s ease; }
@keyframes akDipFade { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
/* título encima de las opciones, en el lado oscuro */
selector .ak-dip-intro { position: absolute !important; top: 109px; left: calc(45.4% - 602px); width: 562px !important; z-index: 2; }
@media (max-width: 1366px) {
  selector .ak-dip-tabs .e-n-tabs { min-height: 600px; }
  selector .ak-dip-tabs .e-n-tabs-heading { padding: 313px 62px 72px 40px; }
  selector .ak-dip-tabs .e-n-tab-title { width: 440px !important; min-height: 72px; gap: 18px !important; }
  selector .ak-dip-tabs .e-n-tab-title-text { gap: 18px; }
  selector .ak-dip-tabs .e-n-tab-title-text::before { width: 28px; height: 28px; }
  selector .ak-dip-ic { width: 48px !important; height: 48px; }
  selector .ak-dip-tabs .e-n-tab-icon i { font-size: 24px; }
  selector .ak-dip-tabs .e-n-tab-icon svg { width: 24px; height: 24px; }
  selector .ak-dip-tabs .e-n-tab-title-text { font-size: 16px !important; }
  selector .ak-dip-tabs .e-n-tabs-content { padding: 64px 40px 60px 80px; }
  selector .ak-dip-tabs .e-n-tabs-content > .e-con { max-width: 520px; }
  selector .ak-dip-intro { top: 80px; left: calc(45.4% - 502px); width: 470px !important; }
  selector .elementor-widget-text-editor p { margin-bottom: 16px; }
}
@media (max-width: 1024px) {
  selector .ak-dip-intro { position: static !important; width: 100% !important; padding: 56px 20px 0; }
  selector .ak-dip-tabs .e-n-tabs { display: flex !important; flex-direction: column !important; min-height: 0; }
  selector .ak-dip-tabs .e-n-tabs-heading { align-items: stretch !important; padding: 28px 20px 40px; }
  selector .ak-dip-tabs .e-n-tab-title { width: 100% !important; min-height: 64px; gap: 14px !important; }
  selector .ak-dip-tabs .e-n-tab-title-text { font-size: 12px !important; }
  selector .ak-dip-tabs .e-n-tab-title-text { gap: 14px; }
  selector .ak-dip-tabs .e-n-tab-title-text::before { width: 22px; height: 22px; }
  selector .ak-dip-ic { width: 42px !important; height: 42px; }
  selector .ak-dip-tabs .e-n-tab-icon i { font-size: 20px; }
  selector .ak-dip-tabs .e-n-tab-icon svg { width: 20px; height: 20px; }
  selector .ak-dip-tabs .e-n-tabs-content { padding: 40px 20px 48px; }
  selector .ak-dip-tabs .e-n-tabs-content > .e-con { max-width: none; }
}
/* ---- móvil (≤767px): acordeón animado. Cada opción abre su descripción justo debajo; desktop/laptop/tablet no cambian ---- */
@media (max-width: 767px) {
  /* Solo durante una animación, accordion.js pone esta clase en <html> para que Chrome no corrija el scroll por su cuenta */
  html.ak-dip-noanchor { overflow-anchor: none; }
  selector .ak-dip-tabs .e-n-tabs { display: flex !important; flex-direction: column !important; min-height: 0 !important; background: #030917; padding: 28px 0 40px !important; }
  selector .ak-dip-tabs .e-n-tabs-heading { display: contents !important; padding: 0 !important; background: none !important; }
  selector .ak-dip-tabs .e-n-tabs-content { display: contents !important; padding: 0 !important; background: none !important; }
  selector .ak-dip-tabs .e-n-tab-title { order: var(--n-tabs-title-order); width: auto !important; margin: 0 20px !important; min-height: 64px; gap: 14px !important; }
  /* Todos los paneles tienen siempre el mismo aspecto (fondo, columna, padding lateral, ancho).
     Lo único que cambia entre cerrado y abierto son height, padding vertical y visibility (y opacity en la animación). */
  selector .ak-dip-tabs .e-n-tabs-content > .e-con { order: var(--n-tabs-title-order); max-width: none !important; display: flex !important; flex-direction: column !important; flex-wrap: nowrap !important; box-sizing: border-box; width: 100%; background: #EBEFF2 !important; padding-left: 20px !important; padding-right: 20px !important; padding-top: 0 !important; padding-bottom: 0 !important; height: 0; overflow: hidden; visibility: hidden; animation: none !important; }
  /* Con altura recortada durante la animación, el contenido no debe repartirse en columnas ni encogerse */
  selector .ak-dip-tabs .e-n-tabs-content > .e-con > * { flex-shrink: 0 !important; }
  selector .ak-dip-tabs .e-n-tabs-content > .e-con.e-active { height: auto; visibility: visible; }
  /* El aire vertical del panel (40px arriba, 48px abajo) va en el contenido y no como padding del panel:
     un padding con !important no se puede animar y hacía que el panel saltara de golpe a 88px al abrir y cerrar. */
  selector .ak-dip-tabs .e-n-tabs-content > .e-con > :first-child { margin-top: 40px !important; }
  selector .ak-dip-tabs .e-n-tabs-content > .e-con > :last-child { margin-bottom: 48px !important; }
  selector .ak-dip-tabs .e-n-tabs.ak-dip-ready .e-n-tab-title::after { transition: transform .48s cubic-bezier(.4,0,.2,1), border-color .3s; }
  selector .ak-dip-tabs .e-n-tab-title[aria-selected="true"]::after { transform: rotate(135deg); }
}
@media (max-width: 767px) and (prefers-reduced-motion: reduce) {
  selector .ak-dip-tabs .e-n-tabs.ak-dip-ready .e-n-tab-title::after { transition: none; }
}
/* el widget HTML (JS) va al final de la sección: que no le añada margen a las pestañas */
selector .ak-dip-tabs { margin-bottom: 0 !important; }
selector .ak-dip-js { margin: 0 !important; padding: 0 !important; }
